sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float copies;
uniform float2 center;
uniform float orbitRadius;
uniform float startAngle;
uniform float spread;
uniform float copyScale;
uniform float faceCenter;
uniform float copyTurn;
uniform float combine;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float4 acc = float4(0.0);
    for (int i = 0; i < 32; i++) {
        if (float(i) >= copies) break;
        float ang = radians(startAngle) + radians(spread) * float(i) / max(copies, 1.0);
        float2 place = ctr + float2(cos(ang), sin(ang)) * orbitRadius;
        float rot = (faceCenter > 0.5 ? ang : 0.0) + radians(copyTurn);
        float2 q = rot2(coord - place, -rot) / copyScale + size * 0.5;
        float4 s4 = texT(q);
        if (combine < 0.5) acc = s4 + acc * (1.0 - s4.a);
        else if (combine < 1.5) acc += s4;
        else if (combine < 2.5) acc = acc + s4 - acc * s4;
        else acc = max(acc, s4);
    }
    return fin(c, acc, opacity);
}
